 (M&P)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"39,561","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"64,900","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"104,461","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"146,467","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PDSI and Elnusa (rupiah)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"5,261","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"30,664","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"35,925","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"14,250","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Gross principal","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,552,114","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,680,531","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"3,232,645","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"4,847,700","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Less arrangement fees","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(1,080)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(4,636)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(5,716)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(14,243)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Long-term bank loans","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,551,034","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,675,895","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"3,226,929","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"4,833,457","type":"text","marks":[{"type":"bold"}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Note 50 reconciles all borrowings, including sukuk and the shareholder loan (Daftar 5/235, PDF p. 252).","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"4,978,575 + drawdowns 56,412 − repayments 1,679,292 + non-cash 5,171 = 3,360,866","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"= short-term 15,775 + long-term 3,226,929 + shareholder loan 74,873 + sukuk 43,289","type":"text"}]}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Share due within one year = 1,551,034 / 3,226,929 = 48.1%","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Implied cost of borrowing = interest on loans 297,328 (Note 41) / average borrowings ((4,978,575 + 3,360,866) / 2 = 4,169,721) = 7.1%, approximate, since the numerator is after 2,277 of interest capitalised (Note 12, PDF p. 126)","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Net debt = 3,360,866 − cash 2,614,318 = 746,548; against total equity 15,107,352 = 0.05","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The last ratio is only a proxy for the covenant, whose definitions of net debt and tangible net worth are not disclosed, but it suggests wide headroom against 2.00. PHE states it complied with all covenants (Note 27). Almost half the line falls due in 2025, mainly the 940,000 bullet. PHE discloses no refinancing of it at the reporting date, and it held cash of 2,614,318. Note 27 shows 560,000 undrawn under the 2023 agreement, without saying whether it was still available (PDF p. 157). The USD 200 million six-month loan PHE took in February 2025 (Note 52c, Daftar 5/237, PDF p. 254) came from PAEP, a wholly owned subsidiary (Note 1), so it leaves consolidated borrowings unchanged; an external loan signed then would not have reclassified the bullet either (para. 72).","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Two disclosures do not follow the rules taught above.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The sukuk matures on 11 August 2025, within twelve months, yet it is presented as non-current on the balance sheet and in the 1–5 year column of the liquidity table (Note 49, Daftar 5/233, PDF p. 250). Under section 5 it should be current.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The liquidity table's \"bank and shareholder loans\" due within a year, 1,566,809, equals long-term current maturities plus short-term loans (1,551,034 + 15,775) and leaves out the 74,873 shareholder loan, as does the 2023 column. It also shows carrying amounts, where PSAK 107 asks for undiscounted contractual cash flows.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"11. Upstream note: project finance at Jambaran-Tiung Biru","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PEPC financed the Jambaran-Tiung Biru gas development through a ","type":"text"},{"text":"trustee borrowing structure","type":"text","marks":[{"type":"italic"}]},{"text":": facilities of 1,679,940 after a 166,460 cancellation. The 122,859 remaining in the trustee accounts is carried as restricted cash (Note 27, PDF pp. 148–150). Half of each tranche's notional is swapped from the floating benchmark to fixed base rates of 1.79–1.99 percent (315,000 of 630,000; 479,970 of 959,940), so half the notional was hedged at the effective date; the swaps' amortisation profile is not disclosed. Tranches amortise semi-annually to 2029 and 2034, the longest-dated part of the line.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"12. Related lines","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"long-term-bank-loans-current","type":"text","marks":[{"type":"code"}]},{"text":", ","type":"text"},{"text":"short-term-bank-loans","type":"text","marks":[{"type":"code"}]},{"text":", ","type":"text"},{"text":"other-loans-current","type":"text","marks":[{"type":"code"}]},{"text":", ","type":"text"},{"text":"sukuk-payables","type":"text","marks":[{"type":"code"}]},{"text":": the rest of PHE's borrowings, covered on this page.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"cash-and-cash-equivalents","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/cash-and-cash-equivalents","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":" and ","type":"text"},{"text":"restricted-cash","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/restricted-cash","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the other side of net debt and the trustee account.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"finance-cost","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/finance-cost","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": interest at the effective rate.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"fixed-assets-net","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/fixed-assets-net","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": capitalised borrowing costs.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"lease-liabilities-current","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/right-of-use-assets-net","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the other interest-bearing debt (see the Right-of-use assets essay).","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3,"textAlign":null},"content":[{"text":"Least-confident assertions","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"That PEP prepaid about 277,000 of its facility A2 in 2024 is inferred from Note 27 and Note 50; PHE does not describe it, and the 8,527 fall in unamortised fees is consistent with but does not prove a write-off.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PHE appears to measure the sukuk ijarah under PSAK 109 rather than PSAK 410. Its policy puts the sukuk among loans at amortised cost by the EIR method, and the amortised costs (83.9 and 61.7 percent of the total at the end of 2024 and 2023) fit an effective-interest pattern (about 82–88 and 60–65 percent) rather than straight line (87.8 and 67.7 percent). With costs of 224 on 43,325 the difference is immaterial. The sukuk is also shown as non-current although it matures in August 2025.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The PSAK 410 treatment in section 8 is from an IAI teaching deck that disclaims being IAI's official view. The standard's text was not opened.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The covenant proxy of 0.05 uses total equity and reported cash. The agreements' definitions are not disclosed.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Other PHE slips not used in the body: Note 27's facility A1 total reads 943,480,000 for 943,840,000 (PDF p. 155); facility interest (299,827 with the shareholder loan) exceeds Note 41's 297,328 by 2,499, mostly the 2,277 capitalised (Note 12), with 222 and the location of the sukuk fee and M&P's interest undisclosed. The industry notes in section 9 are general practice, not checked against named companies.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"References","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PT Pertamina Hulu Energi dan Entitas Anak, consolidated financial statements 31 December 2024 (audited, USD thousand): statement of financial position (Daftar 1/1–1/3, PDF pp. 11–13); Note 1 (subsidiaries); Note 12 (PDF p. 126); cash flow statement (Daftar 4, PDF p. 17); Note 3b (Daftar 5/30, PDF p. 47); Note 3g (Daftar 5/44–5/47, PDF pp. 61–64); Note 22 (Daftar 5/116–5/117, PDF pp. 133–134); Note 26 (Daftar 5/125, PDF p. 142); Note 27 (Daftar 5/130–5/143, PDF pp. 147–160); Note 41 (Daftar 5/150, PDF p. 167); Note 44h–i (Daftar 5/187, PDF p. 204); Note 47 (Daftar 5/222–5/224, PDF pp. 239–241); Note 49 liquidity table (Daftar 5/233, PDF p. 250); Note 50 (Daftar 5/235, PDF p. 252); Note 52c (Daftar 5/237, PDF p. 254). VERIFIED (PHE FS 2024, on disk).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lecture notes this series follows, \"Inter 2 – Chapter 14 – Non Current Liabilities\" (Rumpun Akuntansi Keuangan): bond types, issuing, at par, discount and premium, effective interest, accruing interest, notes at and not at face value, notes for property, imputed interest, mortgage notes, extinguishment by cash, assets, shares and modification, fair value option, off-balance-sheet financing. NOTES. Classification and covenants come from \"Inter 2 – Chapter 13\" (current liabilities). Corrections made here: the notes credit the own-credit gain to income (OCI under PSAK 109), state a 50 percent consolidation test (control under PSAK 110), credit annual interest on a face-value note to the note instead of cash, misprint the depot bond's annuity factor (12.46621 for 12.46221, so the discount is 311,554, not 311,154), and credit Cash in an accrual entry. Sukuk and section 9 have no note.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 109 (IFRS 9), paras. 3.3.1, 3.3.3, 4.2.1(c), 4.2.2, 5.1.1, 5.4.7–5.4.9, 5.7.7, B3.3.6, B5.4.5: 10 percent test VERIFIED (web, IFRS Foundation agenda papers; IFRIC update Nov 2016 via IAS Plus); other paragraphs STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 201 (IAS 1), paras. 60, 69, 72–75; 2022 amendment ","type":"text"},{"text":"Non-current Liabilities with Covenants","type":"text","marks":[{"type":"italic"}]},{"text":", paras. 72B, 76ZA, effective 1 January 2024: amendment content VERIFIED (web, BDO IFR Bulletin 2022/07; EY Developments 209); paras. 60, 69, 72–75 STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 410 ","type":"text"},{"text":"Akuntansi Sukuk","type":"text","marks":[{"type":"italic"}]},{"text":" (formerly PSAK 110): number VERIFIED (web, IAI, ","type":"text"},{"text":"DSAS Terkini","type":"text","marks":[{"type":"italic"}]},{"text":" XV 2023; Binus Accounting, 2024). Issuer measurement and presentation VERIFIED (web, IAI, \"PSAK Syariah for Academics – Akuntansi Sukuk\", 28 Feb 2024, slides 36–40, speaker's personal views; fetched again at recheck).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"ISAK 119 (IFRIC 19), PSAK 220 (IAS 20) para. 10A, PSAK 221 (IAS 21), PSAK 110 (IFRS 10), PSAK 107 (IFRS 7), PSAK 223 (IAS 23): numbers from the IAI renumbering rule (IFRS n → PSAK 100+n, IAS n → PSAK 200+n, IFRIC n → ISAK 100+n); content STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Kieso, Weygandt and Warfield, ","type":"text"},{"text":"Intermediate Accounting","type":"text","marks":[{"type":"italic"}]},{"text":", IFRS edition, ch. 14, the textbook the lecture notes summarise. Not on disk; NOT VERIFIED.","type":"text"}]}]}]}]}$j$::jsonb,
       presentation = $p${"deck":"The theory of long-term borrowings from pricing to derecognition, worked through PHE's syndicated loans and a subsidiary's sukuk ijarah, and set beside the industries that borrow differently","genre":null,"author_bio":null,"references":[],"hero_caption":null,"key_takeaways":["A loan is recognised at the cash actually received, net of the costs of arranging it, and then carried at amortised cost. The effective interest rate spreads coupons, fees, discounts and premiums over the loan's life as one interest expense, so the carrying amount climbs or falls to the amount repayable.","The current/non-current split turns on one question, asked at the reporting date: does the borrower have a right to defer settlement for at least twelve months? Since the 2024 amendments to PSAK 201, only covenants tested on or before that date can take the right away; later covenants are disclosed.","A loan leaves the balance sheet when it is repaid, extinguished or modified so much that it is in substance a new loan (the 10 percent test). Sukuk follow their own standard, PSAK 410: a sukuk ijarah is a liability with costs amortised straight-line, and a sukuk mudharabah is temporary syirkah funds, outside liabilities."],"revision_note":null}$p$::jsonb,
       updated_at = now()
 WHERE id = 'e7716f4d-6d57-443d-9221-92b00916bbd7';
INSERT INTO public.essay_revisions (essay_id, revision_no, change_type, title, snippet, content_json, status, change_summary, changed_by)
SELECT e.id, coalesce((SELECT max(x.revision_no) FROM public.essay_revisions x WHERE x.essay_id = e.id), 0) + 1, 'rollback',
       e.title, e.snippet, e.content_json, e.status, $s$Restored from the snapshot taken before the lecture-notes removal$s$, null
  FROM public.essays e WHERE e.id = 'e7716f4d-6d57-443d-9221-92b00916bbd7';

DO $chk$ BEGIN
  IF (SELECT count(*) FROM public.essays WHERE id IN ('5e8874e3-0e04-4270-ba48-0e7bd2edba2e', '103737ec-579a-4330-a996-adf381d57bbe', 'bfe42851-b6bc-480b-9d14-5572fc9e1272', 'e7716f4d-6d57-443d-9221-92b00916bbd7') AND updated_at = now()) <> 4 THEN
    RAISE EXCEPTION 'Not written: an essay in this part was changed after the snapshot. Nothing in this part was saved.';
  END IF;
END $chk$;
COMMIT;
